"""Turtle / SPARQL literal escape for double-quoted string literals.

Lifted from the canonical Python implementation at
``whatsapp_bridge/bridge.py:212`` (``_escape``) and the gateway's
``services/gateway/src/sparql_escape.py``. CM048 emits Turtle (not
SPARQL UPDATE) but the W3C grammar for STRING_LITERAL_QUOTE is
identical between the two: the same character set must be escaped to
keep an attacker-controllable string trapped inside its surrounding
double-quotes.

Covers:

- ``\\`` -> ``\\\\`` (must be first so we do not double-escape our own
  escapes)
- ``"``  -> ``\\"``
- ``\\n``, ``\\r``, ``\\t`` (newline, carriage return, tab)
- U+2028 LINE SEPARATOR, U+2029 PARAGRAPH SEPARATOR -- Turtle / SPARQL
  serialisers may treat these as literal terminators

Use this for every interpolation into a Turtle ``"..."`` string literal
in the CM048 triple-builders. The pre-existing builders had three
classes of inline interpolation:

1. ``_fact_to_triples`` already passes ``fact["text"]`` through
   ``json.dumps`` -- safe (JSON escape happens to be a strict
   superset of Turtle string-literal escape for the bytes the
   builder interpolates).
2. ``_signal_to_triples`` and ``_conversation_to_triples`` interpolate
   bare LLM-classification values (``warmth``, ``trust``, ``setting``,
   ``shape``, ``stakes``) and ``settings.user_id`` directly into
   ``"..."`` literals with no escape -- this module fixes that.
3. ``_fact_to_triples`` also interpolates ``fact["type"]``,
   ``fact["domain"]``, ``fact["privacy_level"]``, ``fact["signal_strength"]``
   bare. Same fix.
"""

from __future__ import annotations

# Use chr() / ord() to avoid Write-tool encoding ambiguity around the
# U+2028 / U+2029 codepoints. Functionally identical to a string
# literal containing the raw codepoints; just unambiguous in source.
_LINE_SEPARATOR = chr(0x2028)
_PARAGRAPH_SEPARATOR = chr(0x2029)


def escape_turtle_literal(text) -> str:
    """Escape ``text`` for safe insertion into a Turtle ``"..."`` literal.

    Returns the escaped string ready to drop between the outer quotes
    of a Turtle string literal. The caller still owns the surrounding
    quote characters.

    Accepts non-string inputs (``str()``-coerces) so call sites that
    pass through dict ``.get(...)`` defaults of any type stay valid.
    """
    s = text if isinstance(text, str) else str(text)
    return (
        s.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
        .replace(_LINE_SEPARATOR, "\\u2028")
        .replace(_PARAGRAPH_SEPARATOR, "\\u2029")
    )


# ---------------------------------------------------------------------------
# IRI path escape -- the other half of the grammar
# ---------------------------------------------------------------------------
#
# `escape_turtle_literal` above guards Turtle string literals. It does
# nothing for Turtle IRIs, which are a different production with a
# different escape rule, and until 2026-08-23 the IRI half had no guard
# at all. `_urn` interpolated LLM-generated fact subjects straight into
# <urn:ostler:...>, so a subject like "AI researchers" produced
#
#     <urn:ostler:AI researchers>
#
# which is not a legal IRIREF. Oxigraph rejects such a document whole,
# so one prose subject discarded every triple for that conversation.
# Live on a customer box: 26 of 726 sessions stuck, 219 permanent
# errors, a 2.32 MB error log still growing.
#
# The `>` case is worse than the crash and is why this is a security
# fix rather than a robustness one. `<urn:ostler:evil> <p> <o> . <x`
# as a subject closes the IRI early and everything after it is parsed
# as live Turtle -- arbitrary triples written into the operator's
# graph. Fact subjects are generated by an LLM reading conversation
# text, and anyone who can message the operator can influence that
# text. So this input is untrusted in the same sense the literal path
# already assumes.

#: Codepoints the IRIREF production excludes:
#:
#:     [18] IRIREF ::= '<' ([^#x00-#x20<>"{}|^`\] | UCHAR)* '>'
#:     -- https://www.w3.org/TR/turtle/#grammar-production-IRIREF
#:
#: Everything U+0000..U+0020 (the space that broke production lives
#: here) plus the eight named ASCII characters.
_IRIREF_ILLEGAL = frozenset(chr(c) for c in range(0x00, 0x21)) | frozenset('<>"{}|^`\\')

#: Escaped FIRST so the transform stays injective. Without it "a b" and
#: the literal string "a%20b" would both encode to "a%20b" and collapse
#: into one graph node -- two different subjects silently merged. No
#: slug the estate emits today contains '%', so this costs nothing and
#: buys reversibility.
_PERCENT = "%"


def escape_turtle_iri_path(path) -> str:
    """Percent-encode ``path`` so it is safe inside a Turtle ``<...>``.

    Takes the *path portion* of a URN -- the part after the scheme --
    and returns it with every IRIREF-illegal codepoint percent-encoded.
    The caller still owns the ``<urn:ostler:`` prefix and the closing
    ``>``.

    ``/`` is deliberately preserved. It is structural in every CM048
    URI (``other/sam_ng``, ``signal/<conv>/<slug>``) and CM044's
    person-page bridge splits on it:

        _SUBJECT_RE = re.compile(r"^urn:ostler:(?:other|person)/(.+)$")

    Encoding it would break that regex at the separator rather than at
    the slug, which would look like "the LLM changed its slug format"
    and be diagnosed nowhere near here.

    Percent-encoding rather than slugification is a deliberate choice.
    Slugifying is lossy: "AI researchers" and "ai-researchers" would
    collapse to one node, silently merging two distinct subjects.
    Percent-encoding is reversible and collision-free, so a reader that
    wants the display form can recover it, and one that does not still
    gets a stable identity.

    Bit-identical output for anything already legal, which is the whole
    population that binds today -- bridge slugs are ``[a-z0-9_]`` plus
    ``/``. This function cannot unbind an existing fact.

    Accepts non-string input for symmetry with
    :func:`escape_turtle_literal`.
    """
    s = path if isinstance(path, str) else str(path)
    out = []
    for ch in s:
        if ch == _PERCENT or ch in _IRIREF_ILLEGAL:
            # UTF-8 then percent-encode each byte, per RFC 3987 §3.1.
            # Non-ASCII illegals cannot occur (the illegal set is all
            # ASCII) but encoding via utf-8 keeps this correct if the
            # set is ever widened.
            out.extend("%%%02X" % b for b in ch.encode("utf-8"))
        else:
            out.append(ch)
    return "".join(out)
